import{_ as o,o as d,c,a5 as r}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"Spring是什么","description":"","frontmatter":{"title":"Spring是什么","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/Spring是什么.md","filePath":"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/Spring是什么.md"}'),p={name:"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/Spring是什么.md"};function n(t,e,a,i,s,g){return d(),c("div",null,[...e[0]||(e[0]=[r("<div><p><code>Spring</code></p><p>是一个主流的</p><p><code>Java</code></p><p><code>Web</code> 开发框架，该框架是一个轻量级的应用框架，具有很高的凝聚力和吸引力。<code>Spring</code> 框架因其强大的功能以及卓越的性能而受到众多开发人员的喜爱。</p><p><code>Spring</code> 是分层的 <code>Java SE/EE full-stack</code> 轻量级开源框架，以 <code>IoC</code>（<code>Inverse of Control</code>，控制反转）和 <code>AOP</code>（<code>Aspect Oriented Programming</code>，面向切面编程）为内核，使用基本的 <code>JavaBean</code> 完成以前只可能由 <code>EJB</code> 完成的工作，取代了 <code>EJB</code> 臃肿和低效的开发模式。</p><p>在实际开发中，通常服务器端采用三层体系架构，分别为</p><ul><li>表现层（<code>web</code>）</li><li>业务逻辑层（<code>service</code>）</li><li>持久层（<code>dao</code>）</li></ul><p><code>Spring</code> 对每一层都提供了技术支持，在表现层提供了与</p><p><code>Struts2</code></p><p>框架的整合，在业务逻辑层可以管理事务和记录日志等，在持久层可以整合</p><p><code>Hibernate</code></p><p>和 <code>JdbcTemplate</code> 等技术。</p><p>从设计上看，<code>Spring</code> 框架给予了 <code>Java</code> 程序员更高的自由度，对业界的常见问题也提供了良好的解决方案，因此，在开源社区受到了广泛的欢迎，并且被大部分公司作为 <code>Java</code> 项目开发的首选框架。</p><p><code>Spring</code> 具有简单、可测试和松耦合等特点，不仅可以用于服务器端的开发，也可以应用于任何 <code>Java</code> 应用的开发中。<code>Spring</code> 框架的主要优点具体如下。 <code>1</code><strong>）方便解耦，简化开发</strong><code>Spring</code> 就是一个大工厂，可以将所有对象的创建和依赖关系的维护交给 <code>Spring</code> 管理。 <code>2</code><strong>）方便集成各种优秀框架</strong><code>Spring</code> 不排斥各种优秀的开源框架，其内部提供了对各种优秀框架（如 <code>Struts2</code>、<code>Hibernate</code>、<code>MyBatis</code> 等）的直接支持。 <code>3</code><strong>）降低</strong> <code>Java EE API</code> <strong>的使用难度</strong><code>Spring</code> 对 <code>Java EE</code> 开发中非常难用的一些 <code>API</code>（<code>JDBC</code>、<code>JavaMail</code>、远程调用等）都提供了封装，使这些 <code>API</code> 应用的难度大大降低。 <code>4</code><strong>）方便程序的测试</strong><code>Spring</code> 支持 <code>JUnit4</code>，可以通过注解方便地测试 <code>Spring</code> 程序。 <code>5</code><strong>）</strong><code>AOP</code> <strong>编程的支持</strong><code>Spring</code> 提供面向切面编程，可以方便地实现对程序进行权限拦截和运行监控等功能。 <code>6</code><strong>）声明式事务的支持</strong> 只需要通过配置就可以完成对事务的管理，而无须手动编程。</p></div>",1)])])}const _=o(p,[["render",n]]);export{l as __pageData,_ as default};
